import { expect, expectStatus, test } from "../../fixtures";

test("A vendor with all documents extracted is submitted for review", { tag: "@REV-01" }, async ({ apiAs, factory }) => {
  // Arrange
  const member = await apiAs("member");
  const { vendor } = await factory.vendorWithDocuments({ as: "member" });

  // Act
  const response = await member.post(`/api/vendors/${vendor.id}/submit`);

  // Assert
  const body = await expectStatus(response, 200);
  expect(body.status).toBe("in_review");

  // Re-read the vendor: the status must be stored, not just echoed in the submit response.
  const stored = await expectStatus(await member.get(`/api/vendors/${vendor.id}`), 200);
  expect(stored.status).toBe("in_review");

  const audit = await expectStatus(await member.get(`/api/vendors/${vendor.id}/audit`), 200);
  expect(audit.items.map((event: { action: string }) => event.action)).toContain("vendor.submitted");
});
